/** Convert the backslash escapes allowed in Markdown link text and destinations. */
function unescapeMarkdown(value: string): string {
  return value.replace(/\\([\s\S])/g, '$1');
}

function defaultHeadingDisplay(target: string): string | null {
  const hashIndex = target.indexOf('#');
  if (hashIndex === -1) {
    return null;
  }

  const page = target.substring(0, hashIndex);
  const heading = target.substring(hashIndex + 1);
  if (heading.length === 0) {
    return null;
  }

  return page.length === 0 ? heading : `${page} > ${heading}`;
}

function wikiLinkToMarkdown(target: string, display: string | undefined, image: boolean): string {
  const isEmbedSize = display != null && /^\d+(?:x\d+)?$/.test(display);
  const defaultDisplay = image ? target : defaultHeadingDisplay(target) ?? target;
  const text = display == null || isEmbedSize ? defaultDisplay : display;
  return `${image ? '!' : ''}[${text}](${target})`;
}

function convertWikiLinks(text: string, image: boolean): string {
  const marker = image ? '![[' : '[[';
  let result = '';
  let index = 0;

  while (index < text.length) {
    const start = text.indexOf(marker, index);
    if (start === -1) {
      return result + text.substring(index);
    }

    // A link conversion must leave embeds to the independently configured image style.
    if (!image && start > 0 && text[start - 1] === '!') {
      result += text.substring(index, start + marker.length);
      index = start + marker.length;
      continue;
    }

    result += text.substring(index, start);
    const contentStart = start + marker.length;
    const end = text.indexOf(']]', contentStart);
    if (end === -1) {
      return result + text.substring(start);
    }

    const content = text.substring(contentStart, end);
    // This rule intentionally handles only the simple wiki link and embed syntax.
    if (content.includes('\n') || content.includes('[') || content.includes(']')) {
      result += text.substring(start, end + 2);
    } else {
      const separator = content.indexOf('|');
      const target = separator === -1 ? content : content.substring(0, separator);
      const display = separator === -1 ? undefined : content.substring(separator + 1);
      if (target.length === 0 || display?.includes('|')) {
        result += text.substring(start, end + 2);
      } else {
        result += wikiLinkToMarkdown(target, display, image);
      }
    }
    index = end + 2;
  }

  return result;
}

function findClosingBracket(text: string, start: number): number {
  let depth = 0;
  for (let index = start; index < text.length; index++) {
    if (text[index] === '\\') {
      index++;
    } else if (text[index] === '[') {
      depth++;
    } else if (text[index] === ']' && --depth === 0) {
